content.query:
let Incidents = union isfuzzy=true (datatable(IncidentNumber:int, TimeGenerated:datetime, CreatedTime:datetime, ClosedTime:datetime, Severity:string, Status:string)[]), (SecurityIncident | where TimeGenerated {TimeRange} | project IncidentNumber, TimeGenerated, CreatedTime, ClosedTime, Severity, Status);
let LatestIncidents = Incidents | summarize arg_max(TimeGenerated, *) by IncidentNumber;
let Alerts = union isfuzzy=true (datatable(TimeGenerated:datetime, SystemAlertId:string)[]), (SecurityAlert | where TimeGenerated {TimeRange} | project TimeGenerated, SystemAlertId);
let Devices = union isfuzzy=true (datatable(TimeGenerated:datetime, DeviceId:string, OnboardingStatus:string, SensorHealthState:string)[]), (DeviceInfo | where TimeGenerated > ago(2d) | project TimeGenerated, DeviceId, OnboardingStatus, SensorHealthState) | summarize arg_max(TimeGenerated, *) by DeviceId;
let RiskySignins = union isfuzzy=true (datatable(TimeGenerated:datetime, Id:string, RiskLevelDuringSignIn:string, ConditionalAccessStatus:string, ResultType:string)[]), (SigninLogs | where TimeGenerated {TimeRange} | project TimeGenerated, Id, RiskLevelDuringSignIn, ConditionalAccessStatus, ResultType);
union
(LatestIncidents | summarize Value=count() | extend Metric='Incidents detected', Context='Observed Sentinel incidents'),
(LatestIncidents | where Severity =~ 'High' | summarize Value=count() | extend Metric='High-severity incidents', Context='Observed Sentinel incidents'),
(LatestIncidents | summarize Value=countif(Status =~ 'Closed') | extend Metric='Incidents closed', Context='Observed state'),
(Alerts | summarize Value=dcount(SystemAlertId) | extend Metric='Security alerts correlated', Context='Unique observed alerts'),
(Devices | summarize Value=dcountif(DeviceId, OnboardingStatus =~ 'Onboarded') | extend Metric='MDE devices reporting', Context='Reported in last 48 hours'),
(RiskySignins | where RiskLevelDuringSignIn in~ ('medium','high') | summarize Value=countif(ConditionalAccessStatus =~ 'failure' or ResultType != '0') | extend Metric='Risky sign-ins interrupted', Context='Observed blocked or failed sign-ins')
| project Metric, Value, Context

{"__advancedHuntingSettings":true,"query":"let I = IdentityInfo | where Timestamp > ago(30d) | summarize arg_max(Timestamp, *) by AccountObjectId | where IsAccountEnabled;
union
(I | summarize Value=todouble(count()) | extend Metric='Enabled identities', Context='Latest observed inventory'),
(I | summarize Value=todouble(countif(RiskLevel =~ 'High')) | extend Metric='High-risk identities', Context='Requires remediation'),
(I | summarize Value=todouble(countif(array_length(AssignedRoles) > 0)) | extend Metric='Privileged identities', Context='Assigned role inventory')
| project Metric, Value, Context","selectedWorkspaceIds":[]}
